async function sendNotificationEmail({ type, to, template, vars = {} }) {
  try {
    const payload = { type, to, template, vars, from: `TiMat <${EMAIL_EXPEDITEUR}>` };
    const { data: { session } = {} } = await supabase.auth.getSession();
    const jeton = session?.access_token;
    if (!jeton) {
      console.warn("[email] pas de session ouverte : l'envoi est refuse cote serveur");
      return { success: false, error: "session absente" };
    }
    const res = await fetch("/api/send-email", {
      method: "POST",
      headers: { "Content-Type": "application/json", "Authorization": "Bearer " + jeton },
      body: JSON.stringify(payload)
    });
    if (!res.ok) {
      const txt = await res.text().catch(() => "-");
      console.warn("[email] echec envoi :", res.status, txt);
      await logAction("email_send_failed", { table_name: "emails", record_id: type });
      return { success: false, error: "HTTP " + res.status, details: txt };
    }
    const data = await res.json().catch(() => ({}));
    await logAction("email_sent", { table_name: "emails", record_id: type });
    return { success: true, data };
  } catch (e) {
    console.warn("[email] non envoye (API absente ?) :", e.message);
    await logAction("email_send_unavailable", { table_name: "emails", record_id: type });
    return { success: false, error: e.message };
  }
}
async function activerPush(userId) {
  const etat = etatPush();
  if (etat === "impossible-ios") return { etat, message: "Sur iPhone, les notifications ne fonctionnent que si TiMat a \xE9t\xE9 ajout\xE9 \xE0 votre \xE9cran d'accueil. Ajoutez-le, puis revenez ici." };
  if (etat === "non-supporte") return { etat, message: "Ce navigateur ne g\xE8re pas les notifications. Vous continuerez \xE0 les recevoir par e-mail." };
  if (etat === "refuse") return { etat, message: "Les notifications sont bloqu\xE9es pour TiMat dans les r\xE9glages de votre navigateur. Il faut les y r\xE9autoriser." };
  if (!userId) return { etat: "erreur", message: "Vous devez \xEAtre connect\xE9e pour activer les notifications." };
  try {
    const permission = await Notification.requestPermission();
    if (permission !== "granted") return { etat: "refuse", message: "Notifications refus\xE9es. Vous continuerez \xE0 les recevoir par e-mail." };
    const reg = await navigator.serviceWorker.ready;
    const abo = await reg.pushManager.getSubscription() || await reg.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: cleEnOctets(VAPID_PUBLIQUE) });
    const json = abo.toJSON();
    const { error } = await supabase.from("push_subscriptions").upsert({
      user_id: userId,
      endpoint: abo.endpoint,
      subscription: json,
      appareil: nomAppareil()
    }, { onConflict: "endpoint" });
    if (error) return { etat: "erreur", message: "L'abonnement n'a pas pu \xEAtre enregistr\xE9 : " + error.message };
    return { etat: "actif", message: "Notifications activ\xE9es sur cet appareil (" + nomAppareil() + ")." };
  } catch (e) {
    return { etat: "erreur", message: "Les notifications n'ont pas pu \xEAtre activ\xE9es : " + (e && e.message || e) };
  }
}
async function desactiverPush(userId) {
  try {
    const reg = await navigator.serviceWorker.ready;
    const abo = await reg.pushManager.getSubscription();
    if (abo) {
      await supabase.from("push_subscriptions").delete().eq("endpoint", abo.endpoint);
      await abo.unsubscribe();
    }
    return { etat: "inactif", message: "Notifications d\xE9sactiv\xE9es sur cet appareil." };
  } catch (e) {
    return { etat: "erreur", message: String(e && e.message || e) };
  }
}
async function envoyerPush({ userId, titre, corps, url, tag }) {
  if (!userId || !titre) return { envoyes: 0 };
  try {
    const { data: { session } } = await supabase.auth.getSession();
    if (!session?.access_token) return { envoyes: 0 };
    const rep = await fetch("/api/send-push", {
      method: "POST",
      headers: { "Content-Type": "application/json", "Authorization": "Bearer " + session.access_token },
      body: JSON.stringify({ userId, titre, corps, url, tag })
    });
    if (!rep.ok) return { envoyes: 0, erreur: "HTTP " + rep.status };
    return await rep.json();
  } catch (e) {
    return { envoyes: 0, erreur: String(e && e.message || e) };
  }
}
